(()=>{const native=window.fetch.bind(window);function fix(v){if(typeof v==='string'&&(v.startsWith('/assets/')||v.startsWith('/outputs/')))return '/apps/avatar'+v;if(Array.isArray(v))return v.map(fix);if(v&&typeof v==='object')return Object.fromEntries(Object.entries(v).map(([k,x])=>[k,fix(x)]));return v}window.fetch=async(input,init)=>{const request=typeof input==='string'&&input.startsWith('/api/')?'/apps/avatar'+input:input;const res=await native(request,init);if(typeof request==='string'&&request.startsWith('/apps/avatar/api/')&&(res.headers.get('content-type')||'').includes('application/json')){return new Response(JSON.stringify(fix(await res.json())),{status:res.status,statusText:res.statusText,headers:res.headers})}return res}})();